    "select count(p) from Product p where p.price < 10", Long.class
).getSingleResult();
// count NIE uwzglednia jeszcze managed - zapytanie odpytuje surowa baze

// POPRAWNIE: jawny flush() przed zapytaniem HQL
session.setHibernateFlushMode(FlushMode.COMMIT);

Product managed = session.find(Product.class, id);
managed.setPrice(9.99);
session.flush(); // wysyla UPDATE PRZED zapytaniem

Long count = session.createQuery(
    "select count(p) from Product p where p.price < 10", Long.class
).getSingleResult();
// count TERAZ uwzglednia zmiane z managed

